    function validateCreditCard(s) {
        // remove non-numerics
        var v = "0123456789";
        var w = "";
        for (i = 0; i < s.length; i++) {
            x = s.charAt(i);
            if (v.indexOf(x, 0) != -1)
                w += x;
        }
        // validate number
        j = w.length / 2;
        k = Math.floor(j);
        m = Math.ceil(j) - k;
        c = 0;
        for (i = 0; i < k; i++) {
            a = w.charAt(i * 2 + m) * 2;
            c += a > 9 ? Math.floor(a / 10 + a % 10) : a;
        }
        for (i = 0; i < k + m; i++)
            c += w.charAt(i * 2 + 1 - m) * 1;
        return (c % 10 == 0);
    }

    function _getExtraOptionVal(obj, key, defaultVal) {
        if (typeof defaultVal == 'undefined') {
            defaultVal = false;
        }
        return obj ? (obj[key] ? obj[key] : defaultVal) : defaultVal;
    }

    function containsSpecialChars(str) {
          const specialChars =
            /[`!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?~]/;
          return specialChars.test(str);
        }

    /**
     *
     * @param {string} form_id
     * @param {bool} is_submit
     * @param {object} options.autohide type bool/number -- pass seconds in this to hide the validation message in given time
     * @returns {undefined}
     */
    function validateForm(form_id, is_submit, options) {

        jQuery.extend(jQuery.validator.messages, {
            email: "Please enter a valid email address.",
        });

        if (typeof is_submit == 'undefined') {
            is_submit = false;
        }
        var autohide = _getExtraOptionVal(options, 'autohide');

        var fieldRequiredMsg = "This field is required.";
        var fieldDigitsMsg = "Please use numbers only in this field.";
        var fieldGreaterThanZeroMsg = "Please enter a number greater than 0 in this field.";
        var fieldLengthMsg = "Please enter valid value.";
        var fieldAlphnumMsg = "The password should contain combination of characters and numbers.";
        var fieldValidNameMsg = "Only letters and spaces allowed.";
        var fieldValidFullNameMsg = "Please enter full name separated with spaces.";
        var fieldValidHoldernameMsg = "Please enter a valid name.";
        var fieldValidNotNumeicMsg = "Only numeric not allowed.";
        var fieldEmailAvailabilityMsg = "This email address is not available.Please use different.";
        var fieldNotEqualMsg = "Please specify a different (non-default) value.";
        var fieldCcNumberMsg = "Please enter a valid credit card number.";
        var fieldCcTypeMsg = "Credit card number does not match credit card type.";
        var fieldCcExpMsg = "Invalid expiry date.";
        var fieldCcCvnMsg = "Invalid cvv.";
        var fieldDistrict = "Only letters allowed.";


        var validation_rules = {};
        var validation_messages = {};

        jQuery.validator.addMethod("greaterThanZero", function (value, element) {
            return this.optional(element) || (parseFloat(value) > 0);
        }, fieldGreaterThanZeroMsg);

        jQuery.validator.addMethod("alphanumeric", function (value, element) {
            return this.optional(element) || /^(?=.*[a-zA-Z])(?=.*[0-9])/i.test(value);
        }, fieldAlphnumMsg);

        jQuery.validator.addMethod("holdername", function (value, element, param) {
            return this.optional(element) || /^[a-z0-9' ]+$/i.test(value);
        }, fieldValidHoldernameMsg);

        jQuery.validator.addMethod("letterswithspace", function (value, element) {
            return this.optional(element) || /^[a-zA-Z][a-zA-Z ]/i.test(value);
        }, fieldValidNameMsg);

        jQuery.validator.addMethod("wordswithspace", function (value, element) {
            return this.optional(element) || /^[a-zA-Z]{2,}[\s][a-zA-Z ]+/i.test(value);
        }, fieldValidFullNameMsg);

        jQuery.validator.addMethod("notnumeric", function (value, element) {
            if (/^[\d\s]+$/i.test(value.replace(/\+/g, ''))) {
                return this.optional(element) || false;
            } else {
                return this.optional(element) || true;
            }
        }, fieldValidNotNumeicMsg);

        jQuery.validator.addMethod("notspecial", function (value, element) {            
                if(containsSpecialChars(value)){                    
                    return this.optional(element) || false;
                }
                return this.optional(element) || true;

        }, fieldDistrict);

        jQuery.validator.addMethod("fullname_valid", function (value, element) {
            return this.optional(element) || /^[\W\w]{1,}[\s][\W\w ]+/i.test(value);
            //return this.optional(element) || /^([^\x00-\x7F]|[a-zA-Z]){2,}[\s]([^\x00-\x7F]|[a-zA-Z ])+/i.test(value);
        }, fieldValidFullNameMsg);

        jQuery.validator.addMethod("checkavailability", function (value, element) {
            this.settings.onkeyup = false;
            var validation;
            $.ajax({
                url: element.getAttribute("data-checkurl"),
                type: 'POST',
                async: false,
                data: {value: value},
                dataType: 'json',
                success: function (data) {
                    if (data.success) {
                        validation = false;
                    } else {
                        validation = true;
                    }
                }});
            return validation;
        }, fieldEmailAvailabilityMsg);

        jQuery.validator.addMethod("notEqualTo", function (value, element, param) {
            return this.optional(element) || value != jQuery(param).val();
        }, fieldNotEqualMsg);


        jQuery.validator.methods.email = function (value, element) {
            return this.optional(element) || /^([\w-]+(?:\.[\w-]+)*)@((?:[\w-]+\.)*\w[\w-]{0,66})\.([a-z]{2,6}(?:\.[a-z]{2})?)$/i.test(value);
        }


        jQuery.validator.addMethod("validateCcNumber", function (value, element, param) {
            var ccType = '';
            var ccTypeContainer = jQuery("#" + element.getAttribute('id').substr(0, element.getAttribute('id').indexOf('_cc_number')) + '_cc_type');
            if (ccTypeContainer) {
                ccType = ccTypeContainer.val();
            }

            var creditCardTypes = getCreditCardTypes();
            if (typeof creditCardTypes[ccType] != 'undefined'
                    && creditCardTypes[ccType][2] == false) {
                if (!(value == '' || (value == null) || (value.length == 0) || /^\s+$/.test(value) || !/[^\d]/.test(value))) {
                    return true;
                } else {
                    return false;
                }
            }
            return validateCreditCard(value);
        }, fieldCcNumberMsg);

        jQuery.validator.addMethod("validateCcType", function (value, element, param) {
            var ccTypeContainer = jQuery("#" + element.getAttribute('id').substr(0, element.getAttribute('id').indexOf('_cc_number')) + '_cc_type');
            if (!ccTypeContainer) {
                return true;
            }
            var ccType = ccTypeContainer.val();

            var creditCardTypes = getCreditCardTypes();
            if (typeof creditCardTypes[ccType] == 'undefined') {
                return false;
            }

            // Other card type or switch or solo card
            if (creditCardTypes[ccType][0] == false) {
                return true;
            }

            if (!value.match(creditCardTypes[ccType][0])) {
                return false;
            }

            return true;
        }, fieldCcTypeMsg);

        jQuery.validator.addMethod("validateCcExp", function (value, element, param) {
            var ccExpMonth = value;
            var ccExpYear = jQuery("#" + element.getAttribute('id').substr(0, element.getAttribute('id').indexOf('_expiration')) + '_expiration_yr').val();
            var currentTime = new Date();
            var currentMonth = currentTime.getMonth() + 1;
            var currentYear = currentTime.getFullYear();
            if (ccExpMonth < currentMonth && ccExpYear == currentYear) {
                return false;
            }
            return true;
        }, fieldCcExpMsg);

        jQuery.validator.addMethod("validateCcExpDate", function (value, element, param) {
            var ccExpMonth = parseInt(jQuery('#cc_expiration').val());
            var ccExpYear = parseInt(jQuery('#cc_expiration_yr').val());
            var currentTime = new Date();
            var currentMonth = currentTime.getMonth() + 1;
            var currentYear = currentTime.getFullYear();
            if ((ccExpMonth < currentMonth && ccExpYear == currentYear) || ccExpYear < currentYear) {
                console.log("currentYear", currentYear);
                return false;
            }
            return true;
        }, fieldCcExpMsg);

        jQuery.validator.addMethod("validateCcCvn", function (value, element, param) {
            var ccTypeContainer = jQuery("#" + element.getAttribute('id').substr(0, element.getAttribute('id').indexOf('_cc_cid')) + '_cc_type');
            if (!ccTypeContainer) {
                return true;
            }
            var ccType = ccTypeContainer.val();

            var creditCardTypes = getCreditCardTypes();
            if (typeof creditCardTypes[ccType] == 'undefined') {
                return false;
            }

            var re = creditCardTypes[ccType][1];
            if (value.match(re)) {
                return true;
            }

            return false;
        }, fieldCcCvnMsg);

